"""Writes content/w2p3.json. ERIC counts come from eric_counts.json (taken on build day); the mock-up numbers from the Lab 1 simulated cohort."""
import json, os, pandas as pd
HERE = os.path.dirname(os.path.abspath(__file__)); K = os.path.join(HERE, '..')
E = json.load(open(f'{HERE}/eric_counts.json', encoding='utf8')); Q = {k: v['n'] for k, v in E['queries'].items()}; RETR = E['retrieved']
